import sys

class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

def reverse_list(head):
    prev = None
    curr = head
    while curr:
        next_node = curr.next
        curr.next = prev
        prev = curr
        curr = next_node
    return prev

def is_palindrome(head):
    if not head or not head.next:
        return True

    slow = head
    fast = head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next

    second_half = reverse_list(slow)
    first_half = head
    result = True

    while second_half:
        if first_half.data != second_half.data:
            result = False
            break
        first_half = first_half.next
        second_half = second_half.next

    return result

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        values = []
        for _ in range(n):
            values.append(int(next(iterator)))
    except StopIteration:
        return

    if n == 0:
        print(0)
        return

    head = Node(values[0])
    current = head
    for i in range(1, n):
        current.next = Node(values[i])
        current = current.next

    if is_palindrome(head):
        print(1)
    else:
        print(0)

if __name__ == "__main__":
    main()
